@props(['title' => 'Administración', 'dataset' => 'products', 'report' => false, 'embedded' => false])
<section class="blade-admin-workspace" x-data="adminPreview(@js($dataset))">
 @unless($embedded)<x-admin.navigation />@endunless
 <div class="min-w-0"><header class="dash-intro"><div><p>REFUGIO OUTDOOR · VISTA PREVIA</p><h1>{{ $title }}</h1><span x-text="dataset.description"></span></div><a href="{{ route('dashboard') }}">Mi cuenta →</a></header>
 <p class="blade-status">Datos de demostración. Las acciones solo modifican esta vista y no guardan cambios en MariaDB.</p>
 @if($report)<x-admin.overview />@endif
 @if($embedded)<label class="block my-4">Módulo de ejemplo <select x-model="key" @change="query = ''; status = ''; page = 1"><template x-for="(table, id) in datasets" :key="id"><option :value="id" x-text="table.title"></option></template></select></label>@endif
 <section class="blade-panel"><div class="blade-actions justify-between mb-4"><h2 class="text-xl font-bold" x-text="dataset.title"></h2><button class="store-button primary" type="button" @click="create()">Nuevo ejemplo</button></div>
 <div class="blade-toolbar"><label>Buscar<input type="search" x-model="query" @input="page = 1" placeholder="Buscar en los ejemplos"></label><label>Estado<select x-model="status" @change="page = 1"><option value="">Todos</option><template x-for="value in statuses" :key="value"><option :value="value" x-text="value"></option></template></select></label><label>Desde<input type="date" x-model="from" @change="page = 1"></label><label>Hasta<input type="date" x-model="until" :min="from" @change="page = 1"></label><button class="text-button" @click="query = ''; status = ''; from = ''; until = ''; page = 1">Limpiar</button></div>
 <p class="page-note mb-4" x-show="from || until">Los filtros de fecha se aplican a las filas de ejemplo que incluyen fecha.</p>
 <div class="blade-table-wrap"><table class="blade-table"><caption class="sr-only">Tabla de demostración, sin conexión comercial al servidor</caption><thead><tr><template x-for="column in dataset.columns" :key="column"><th scope="col" x-text="column"></th></template><th scope="col">Estado</th><th scope="col">Acciones de muestra</th></tr></thead><tbody><template x-for="row in rows" :key="row.id"><tr><template x-for="(cell,index) in row.cells" :key="index"><td x-text="cell"></td></template><td><span class="blade-chip" x-text="row.status"></span></td><td><div class="blade-actions"><button class="text-button" type="button" @click="inspect(row)">Ver</button><button class="text-button" type="button" @click="edit(row)">Editar</button><button class="text-button" type="button" @click="toggle(row)">Alternar estado</button><button class="text-button" type="button" @click="remove(row)">Retirar ejemplo</button></div></td></tr></template></tbody></table></div><p class="store-empty" x-show="filtered.length === 0" x-cloak>No hay resultados con estos filtros.</p>
 <div class="blade-actions justify-between mt-5"><span role="status" x-text="filtered.length + ' filas de ejemplo · Página ' + Math.min(page,pages) + ' de ' + pages"></span><div class="blade-actions"><button class="store-button" type="button" :disabled="page <= 1" @click="page--">Anterior</button><button class="store-button" type="button" :disabled="page >= pages" @click="page++">Siguiente</button></div></div><p class="page-note">Paginación local de ejemplos. La conexión futura utilizará la paginación nativa de Laravel; no se ha integrado DataTables.</p>
 </section><p class="blade-status" x-show="feedback" x-text="feedback" role="status" x-cloak></p>
 <dialog class="blade-dialog" x-ref="details" aria-labelledby="preview-detail-title"><h2 class="text-xl font-bold mb-4" id="preview-detail-title">Detalle de ejemplo</h2><template x-if="selected"><dl><template x-for="(value,index) in selected.cells" :key="index"><div class="py-2"><dt class="font-bold" x-text="dataset.columns[index]"></dt><dd x-text="value"></dd></div></template></dl></template><button class="store-button mt-4" @click="$refs.details.close()">Cerrar</button></dialog>
 <dialog class="blade-dialog" x-ref="editor" aria-labelledby="preview-editor-title"><h2 class="text-xl font-bold" id="preview-editor-title">Formulario de muestra</h2><p class="page-note mb-4">Validación visual sin persistencia. No modifica productos reales.</p><form class="blade-form" @submit.prevent="submit()"><label>Referencia / SKU<input required maxlength="64" x-model="preview.sku"></label><label>Nombre<input required maxlength="150" pattern="[A-Za-z0-9 ]+" title="Solo letras sin acentos, números y espacios" x-model="preview.name"></label><div class="blade-columns"><label>Precio MXN de ejemplo<input type="number" min="0.01" step="0.01" required x-model="preview.mxn"></label><label>Precio USD de ejemplo<input type="number" min="0.01" step="0.01" required x-model="preview.usd"></label></div><label>Stock de ejemplo<input type="number" min="0" step="1" required x-model="preview.stock"></label><label>URL externa de imagen<input type="url" placeholder="https://ejemplo.com/imagen.jpg" required></label><label>Vigente desde<input type="date" required></label><label>Vigente hasta<input type="date"></label><label class="flex-row"><input type="checkbox" checked> Activo · Ejemplo</label><div class="blade-actions"><button class="store-button primary" type="submit">Validar vista previa</button><button class="store-button" type="button" @click="$refs.editor.close()">Cancelar</button></div></form></dialog>
 <dialog class="blade-dialog" x-ref="removal" aria-labelledby="preview-removal-title"><h2 class="text-xl font-bold mb-4" id="preview-removal-title">¿Retirar la fila de ejemplo?</h2><p>Solo desaparecerá de esta vista hasta recargar la página. No se elimina ningún registro real.</p><div class="blade-actions mt-5"><button class="store-button primary" @click="confirmRemove()">Retirar ejemplo</button><button class="store-button" @click="$refs.removal.close()">Cancelar</button></div></dialog>
 </div>
</section>
